\begin{lemma}\label{lem:counterexample}
    Consider a collaboration strategy $\CC$. Suppose that there exists a tuple $(p_1,p_2,\cdots,p_n)\in (0,1)^n$ where $p_k\neq \frac{1}{2}$ and $\CC(p_1,p_2,\cdots,p_n)\neq \round{p_k}.$ Then there exists a collaboration setting $S_k$ such that
    \begin{itemize}
        \item[(i)] $\acc_k(S_k)>\acc_\CC(S_k)$,
        \item[(ii)]
        $\acc_i(S_k)\ge \acc_\CC(S_k)$ for all $i\neq k$.
    \end{itemize}
\end{lemma}

